#!/usr/bin/env python3
"""
Replace the auto-generated documentation block inside an MDX file
with fresh content produced by Pocketflow.

Usage:
    python ecosystem/third_party/pocketflow/scripts/update_mdx_section.py \
        --tool rescontract \
        --body-file /tmp/rescontract_body.md
"""

from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
from pathlib import Path

# .../ecosystem/third_party/pocketflow/scripts/update_mdx_section.py
POCKETFLOW_DIR = Path(__file__).resolve().parents[1]
REPO_ROOT = POCKETFLOW_DIR.parents[2]
DEFAULT_TEMPLATE = """# {title}

{{/* BEGIN AUTO_DOC: {name} */}}

<!-- Pocketflow will overwrite this block -->

{{/* END AUTO_DOC: {name} */}}
"""


def load_tool_map() -> list[dict]:
    tool_map_path = POCKETFLOW_DIR / "tool-doc-map.json"
    try:
        with tool_map_path.open("r", encoding="utf-8") as fh:
            return json.load(fh)
    except FileNotFoundError as exc:
        raise SystemExit(f"tool map not found at {tool_map_path}") from exc


def find_tool_entry(tool_name: str, tool_map: list[dict]) -> dict:
    for entry in tool_map:
        if entry.get("name") == tool_name:
            return entry
    raise SystemExit(f"tool '{tool_name}' missing from tool-doc-map.json")


def ensure_doc_file(path: Path, tool_name: str) -> None:
    if path.exists():
        return

    path.parent.mkdir(parents=True, exist_ok=True)
    template = DEFAULT_TEMPLATE.format(name=tool_name, title=tool_name.title())
    with path.open("w", encoding="utf-8") as fh:
        fh.write(template.strip() + "\n")
    print(f"[update-mdx] Created placeholder template at {path}")


def replace_block(original: str, tool_name: str, body: str) -> str:
    start_marker = f"{{/* BEGIN AUTO_DOC: {tool_name} */}}"
    end_marker = f"{{/* END AUTO_DOC: {tool_name} */}}"

    start_idx = original.find(start_marker)
    end_idx = original.find(end_marker)

    if start_idx == -1 or end_idx == -1:
        raise SystemExit(
            f"Markers not found in MDX file. Expected '{start_marker}' and '{end_marker}'."
        )
    if end_idx <= start_idx:
        raise SystemExit("END marker appears before BEGIN marker.")

    before = original[: start_idx + len(start_marker)]
    after = original[end_idx:]

    body_normalized = "\n\n" + body.strip() + "\n\n"
    return before + body_normalized + after


def run_prettier(path: Path) -> None:
    cmd = ["npx", "prettier", "--write", str(path)]
    try:
        completed = subprocess.run(
            cmd, cwd=REPO_ROOT, capture_output=True, text=True, check=True
        )
        if completed.stdout:
            print(completed.stdout.strip())
        if completed.stderr:
            print(completed.stderr.strip())
    except FileNotFoundError:
        print("[update-mdx] Prettier not found (npx missing). Skipping formatting.")
    except subprocess.CalledProcessError as exc:
        print(f"[update-mdx] Prettier failed: {exc.stderr.strip()}")


def main() -> None:
    parser = argparse.ArgumentParser(description="Update MDX auto-doc section.")
    parser.add_argument("--tool", required=True, help="Tool name in tool-doc-map.json")
    parser.add_argument(
        "--body-file", required=True, help="Path to file containing markdown body"
    )
    parser.add_argument(
        "--skip-format",
        action="store_true",
        help="Skip running Prettier after updating the MDX file.",
    )
    args = parser.parse_args()

    body_path = Path(args.body_file)
    if not body_path.exists():
        raise SystemExit(f"Body file not found: {body_path}")

    tool_map = load_tool_map()
    entry = find_tool_entry(args.tool, tool_map)

    doc_rel_path = entry.get("doc_path")
    if not doc_rel_path:
        raise SystemExit(f"'doc_path' missing for tool {args.tool}")
    doc_path = REPO_ROOT / doc_rel_path

    ensure_doc_file(doc_path, args.tool)
    body = body_path.read_text(encoding="utf-8")
    original = doc_path.read_text(encoding="utf-8")
    updated = replace_block(original, args.tool, body)
    doc_path.write_text(updated, encoding="utf-8")
    print(f"[update-mdx] Updated {doc_path}")

    if not args.skip_format:
        run_prettier(doc_path)


if __name__ == "__main__":
    try:
        main()
    except SystemExit as exc:
        print(exc, file=sys.stderr)
        raise

import os
import fnmatch
import pathspec


def crawl_local_files(
    directory,
    include_patterns=None,
    exclude_patterns=None,
    max_file_size=None,
    use_relative_paths=True,
):
    """
    Crawl files in a local directory with similar interface as crawl_github_files.
    Args:
        directory (str): Path to local directory
        include_patterns (set): File patterns to include (e.g. {"*.py", "*.js"})
        exclude_patterns (set): File patterns to exclude (e.g. {"tests/*"})
        max_file_size (int): Maximum file size in bytes
        use_relative_paths (bool): Whether to use paths relative to directory

    Returns:
        dict: {"files": {filepath: content}}
    """
    if not os.path.isdir(directory):
        raise ValueError(f"Directory does not exist: {directory}")

    files_dict = {}

    # --- Load .gitignore ---
    gitignore_path = os.path.join(directory, ".gitignore")
    gitignore_spec = None
    if os.path.exists(gitignore_path):
        try:
            with open(gitignore_path, "r", encoding="utf-8-sig") as f:
                gitignore_patterns = f.readlines()
            gitignore_spec = pathspec.PathSpec.from_lines("gitwildmatch", gitignore_patterns)
            print(f"Loaded .gitignore patterns from {gitignore_path}")
        except Exception as e:
            print(f"Warning: Could not read or parse .gitignore file {gitignore_path}: {e}")

    all_files = []
    for root, dirs, files in os.walk(directory):
        # Filter directories using .gitignore and exclude_patterns early
        excluded_dirs = set()
        for d in dirs:
            dirpath_rel = os.path.relpath(os.path.join(root, d), directory)

            if gitignore_spec and gitignore_spec.match_file(dirpath_rel):
                excluded_dirs.add(d)
                continue

            if exclude_patterns:
                for pattern in exclude_patterns:
                    if fnmatch.fnmatch(dirpath_rel, pattern) or fnmatch.fnmatch(d, pattern):
                        excluded_dirs.add(d)
                        break

        for d in dirs.copy():
            if d in excluded_dirs:
                dirs.remove(d)

        for filename in files:
            filepath = os.path.join(root, filename)
            all_files.append(filepath)

    total_files = len(all_files)
    processed_files = 0

    for filepath in all_files:
        relpath = os.path.relpath(filepath, directory) if use_relative_paths else filepath

        # --- Exclusion check ---
        excluded = False
        if gitignore_spec and gitignore_spec.match_file(relpath):
            excluded = True

        if not excluded and exclude_patterns:
            for pattern in exclude_patterns:
                if fnmatch.fnmatch(relpath, pattern):
                    excluded = True
                    break

        included = False
        if include_patterns:
            for pattern in include_patterns:
                if fnmatch.fnmatch(relpath, pattern):
                    included = True
                    break
        else:
            included = True

        processed_files += 1 # Increment processed count regardless of inclusion/exclusion

        status = "processed"
        if not included or excluded:
            status = "skipped (excluded)"
            # Print progress for skipped files due to exclusion
            if total_files > 0:
                percentage = (processed_files / total_files) * 100
                rounded_percentage = int(percentage)
                print(f"\033[92mProgress: {processed_files}/{total_files} ({rounded_percentage}%) {relpath} [{status}]\033[0m")
            continue # Skip to next file if not included or excluded

        if max_file_size and os.path.getsize(filepath) > max_file_size:
            status = "skipped (size limit)"
            # Print progress for skipped files due to size limit
            if total_files > 0:
                percentage = (processed_files / total_files) * 100
                rounded_percentage = int(percentage)
                print(f"\033[92mProgress: {processed_files}/{total_files} ({rounded_percentage}%) {relpath} [{status}]\033[0m")
            continue # Skip large files

        # --- File is being processed ---        
        try:
            with open(filepath, "r", encoding="utf-8-sig") as f:
                content = f.read()
            files_dict[relpath] = content
        except Exception as e:
            print(f"Warning: Could not read file {filepath}: {e}")
            status = "skipped (read error)"

        # --- Print progress for processed or error files ---
        if total_files > 0:
            percentage = (processed_files / total_files) * 100
            rounded_percentage = int(percentage)
            print(f"\033[92mProgress: {processed_files}/{total_files} ({rounded_percentage}%) {relpath} [{status}]\033[0m")

    return {"files": files_dict}


if __name__ == "__main__":
    print("--- Crawling parent directory ('..') ---")
    files_data = crawl_local_files(
        "..",
        exclude_patterns={
            "*.pyc",
            "__pycache__/*",
            ".venv/*",
            ".git/*",
            "docs/*",
            "output/*",
        },
    )
    print(f"Found {len(files_data['files'])} files:")
    for path in files_data["files"]:
        print(f"  {path}")

