          }}
          showLineNumbers={showLineNumbers}
          lineNumberStyle={{
            color: 'hsl(var(--muted-foreground))',
            paddingRight: '1rem',
            minWidth: '2.5rem',
          }}
          codeTagProps={{
            className: 'font-mono text-sm',
          }}
          className="dark:hidden"
          wrapLines={true}
          wrapLongLines={true}
        >
          {code}
        </SyntaxHighlighter>
        <SyntaxHighlighter
