import { ActionIcon, Tooltip, Paper, Text, Group, Box, Modal, Textarea, Button, Stack, Divider, Avatar, Switch, Badge } from '@mantine/core';
import { IconBrain, IconSend, IconRobot, IconUser, IconHighlight, IconSettings } from '@tabler/icons-react';
import { useState, useEffect, ReactNode, useCallback, useRef } from 'react';
import ReactMarkdown from 'react-markdown';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { vscDarkPlus } from 'react-syntax-highlighter/dist/cjs/styles/prism';

interface CodeProps {
  node?: any;
  inline?: boolean;
  className?: string;
  children?: ReactNode;
  [key: string]: any;
}

interface MarkdownComponentProps {
  children: ReactNode;
}

export function FloatingAssistant() {
  const [isOpen, setIsOpen] = useState(false);
  const [selectedText, setSelectedText] = useState('');
  const [explanation, setExplanation] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [question, setQuestion] = useState('');
  const [isAskingQuestion, setIsAskingQuestion] = useState(false);
  const [debounceTimer, setDebounceTimer] = useState<NodeJS.Timeout | null>(null);
  const [lastSelection, setLastSelection] = useState('');
  const [highlightMode, setHighlightMode] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const triggerRef = useRef<HTMLButtonElement | null>(null);
  const firstFocusRef = useRef<HTMLTextAreaElement | HTMLButtonElement | null>(null);
  const lastFocusedRef = useRef<HTMLElement | null>(null);
  const switchRef = useRef<HTMLInputElement | null>(null);

  // Function to check if element is within a code editor
  const isWithinCodeEditor = (element: Element | null): boolean => {
    if (!element) return false;

    // Check if element is within a code editor
    if (element.closest('.cm-editor') || 
        element.closest('.CodeMirror') || 
        element.closest('pre') || 
        element.closest('code')) {
      return true;
    }

    // Check parent elements
    return isWithinCodeEditor(element.parentElement);
  };

  // Debounced text selection handler
  const handleTextSelection = useCallback(() => {
    // Only handle text selection if highlight mode is enabled
    if (!highlightMode) return;

    // Clear any existing timer
    if (debounceTimer) {
      clearTimeout(debounceTimer);
    }

    // Set new timer
    const timer = setTimeout(() => {
      const selection = window.getSelection();
      const selectedText = selection?.toString().trim() || '';

      // Don't trigger if:
      // 1. No text is selected
      // 2. Selection is within a code editor
      // 3. Selection is the same as last time
      if (!selectedText || 
          isWithinCodeEditor(selection?.anchorNode?.parentElement as Element | null) ||
          selectedText === lastSelection) {
        return;
      }

      setLastSelection(selectedText);
      setSelectedText(selectedText);
      setIsOpen(true);
      getExplanation(selectedText);
    }, 300); // 300ms debounce delay

    setDebounceTimer(timer);
  }, [debounceTimer, lastSelection, highlightMode]);

  // Cleanup timer on unmount
  useEffect(() => {
    return () => {
      if (debounceTimer) {
        clearTimeout(debounceTimer);
      }
    };
  }, [debounceTimer]);

  // Add event listener for text selection
  useEffect(() => {
    document.addEventListener('mouseup', handleTextSelection);
    return () => {
      document.removeEventListener('mouseup', handleTextSelection);
    };
  }, [handleTextSelection]);

  // Reset lastSelection when modal is closed
  const handleModalClose = () => {
    setIsOpen(false);
    setSelectedText('');
    setExplanation('');
    setQuestion('');
    setLastSelection('');
    // return focus to trigger
    setTimeout(() => {
      try {
        lastFocusedRef.current?.focus?.();
      } catch (err) {}
    }, 0);
  };

  const openModal = (from?: HTMLElement | null) => {
    lastFocusedRef.current = from ?? (document.activeElement as HTMLElement | null);
    setIsOpen(true);
    setTimeout(() => {
      // focus the textarea input if present
      const textarea = document.querySelector('textarea[placeholder]') as HTMLTextAreaElement | null;
      (firstFocusRef.current as HTMLElement | null ?? textarea)?.focus?.();
    }, 50);
  };

  // Escape handler while modal is open
  useEffect(() => {
    if (!isOpen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        handleModalClose();
      }
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [isOpen]);

  // Focus the highlight switch when settings panel is opened
  useEffect(() => {
    if (!showSettings) return;
    setTimeout(() => {
      try {
        switchRef.current?.focus?.();
      } catch (err) {}
    }, 50);
  }, [showSettings]);

  const getExplanation = async (text: string, customQuestion?: string) => {
    setIsLoading(true);
    try {
      const response = await fetch('/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          messages: [
            {
              role: 'user',
              content: customQuestion 
                ? (selectedText 
                    ? `Regarding this text: "${selectedText}"\n\n${customQuestion}`
                    : customQuestion)
                : `Explain the following text or concept in detail:
${text}

Please:
1. Break down any complex concepts
2. Provide examples if relevant
3. Explain any technical terms
4. Use markdown formatting for better readability`
            }
          ]
        }),
      });

      if (!response.ok) throw new Error('Failed to get explanation');

      const reader = response.body?.getReader();
      if (!reader) throw new Error('No reader available');

      let explanation = '';
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const text = new TextDecoder().decode(value);
        explanation += text;
        setExplanation(explanation);
      }
    } catch (error) {
      console.error('Error getting explanation:', error);
      setExplanation('Sorry, there was an error getting the explanation.');
    } finally {
      setIsLoading(false);
      setIsAskingQuestion(false);
    }
  };

  const handleAskQuestion = (e: React.FormEvent) => {
    e.preventDefault();
    if (!question.trim()) return;

    setIsAskingQuestion(true);
    getExplanation(selectedText || '', question);
    setQuestion('');
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      if (question.trim()) {
        setIsAskingQuestion(true);
        getExplanation(selectedText || '', question);
        setQuestion('');
      }
    }
  };

  return (
    <>
