              overflow: 'hidden',
            }}
            ref={triggerRef}
            onClick={(e) => openModal(e.currentTarget)}
            tabIndex={0}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                openModal(e.currentTarget as HTMLElement);
