                    justifyContent: 'center',
                  }}
                >
                  <IconUser size={14} style={{ color: 'rgba(255,255,255,0.7)' }} />
                </div>
                <Box style={{ flex: 1 }}>
                  <Text size="sm" fw={500} mb={4} c="rgba(255,255,255,0.9)">
                    Selected Text
                  </Text>
                  <Text size="sm" c="rgba(255,255,255,0.7)" style={{ lineHeight: 1.5 }}>
                    {selectedText}
                  </Text>
                </Box>
              </Group>
            </div>
          )}

          <Box 
            style={{ 
              flex: 1,
              overflowY: 'auto',
              padding: '1rem',
              display: 'flex',
              flexDirection: 'column',
              gap: '1rem',
            }}
          >
            {isLoading ? (
