          onChange={(val) => handleNumberChange('fetchInterval', val)}
          min={5000}
          max={300000}
          step={5000}
          defaultValue={30000}
        />
      </Box>

      <Paper withBorder p="xs">
        <Code block>{generatedCode}</Code>
      </Paper>
    </Box>
  );
}

