                setSelectedKeyPairIndex(index);

                // Generate and set the ownerAddress
                const ownerAddress = generateOwnerAddress(loadedKeyPairs[index].publicKey);
                setOwnerAddress(ownerAddress);

              } else if (loadedKeyPairs.length > 0) {
